@* Stepper.razor *@
<button @onclick="() => Change(-1)">-</button>
<span>@Value</span>
<button @onclick="() => Change(1)">+</button>

@code {
    [Parameter] public int Value { get; set; }
    [Parameter] public EventCallback<int> ValueChanged { get; set; }

    private async Task Change(int delta)
    {
        await ValueChanged.InvokeAsync(Value + delta);
    }
}

@* SearchBox.razor *@
<input @bind:get="Text" @bind:set="OnTextChanged" @bind:event="oninput" />

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> TextChanged { get; set; }

    private async Task OnTextChanged(string value)
    {
        await TextChanged.InvokeAsync(value);
    }
}
